returns jsonb language sql immutable set search_path='' as $$
 select '{"rail_boarding_documents":{"scene":"rail","claims":[{"subjectId":"rail_eticket_boarding","predicate":"requires_document","objectId":"original_valid_booking_id"},{"subjectId":"rail_eticket_boarding","predicate":"requires_document","objectId":"valid_ticket_not_itinerary_or_receipt"}]},"payment_card_acceptance":{"scene":"payment","claims":[{"subjectId":"international_card_payment","predicate":"requires_action","objectId":"merchant_acceptance_check"}]},"payment_mobile_setup":{"scene":"payment","claims":[{"subjectId":"alipay_weixin_pay","predicate":"offers_procedure","objectId":"supported_card_merchant_qr_payment"}]},"payment_cash_access":{"scene":"payment","claims":[{"subjectId":"rmb_cash_access","predicate":"offers_procedure","objectId":"international_card_atm_withdrawal"},{"subjectId":"rmb_cash_access","predicate":"offers_procedure","objectId":"marked_currency_exchange"}]},"payment_card_and_mobile":{"scene":"payment","claims":[{"subjectId":"international_card_payment","predicate":"requires_action","objectId":"merchant_acceptance_check"},{"subjectId":"alipay_weixin_pay","predicate":"offers_procedure","objectId":"supported_card_merchant_qr_payment"}]},"payment_card_and_cash":{"scene":"payment","claims":[{"subjectId":"international_card_payment","predicate":"requires_action","objectId":"merchant_acceptance_check"},{"subjectId":"rmb_cash_access","predicate":"offers_procedure","objectId":"international_card_atm_withdrawal"},{"subjectId":"rmb_cash_access","predicate":"offers_procedure","objectId":"marked_currency_exchange"}]},"payment_mobile_and_cash":{"scene":"payment","claims":[{"subjectId":"alipay_weixin_pay","predicate":"offers_procedure","objectId":"supported_card_merchant_qr_payment"},{"subjectId":"rmb_cash_access","predicate":"offers_procedure","objectId":"international_card_atm_withdrawal"},{"subjectId":"rmb_cash_access","predicate":"offers_procedure","objectId":"marked_currency_exchange"}]},"payment_getting_started":{"scene":"payment","claims":[{"subjectId":"international_card_payment","predicate":"requires_action","objectId":"merchant_acceptance_check"},{"subjectId":"alipay_weixin_pay","predicate":"offers_procedure","objectId":"supported_card_merchant_qr_payment"},{"subjectId":"rmb_cash_access","predicate":"offers_procedure","objectId":"international_card_atm_withdrawal"},{"subjectId":"rmb_cash_access","predicate":"offers_procedure","objectId":"marked_currency_exchange"}]},"connectivity_sim_documents":{"scene":"connectivity","claims":[{"subjectId":"china_carrier_sim_application","predicate":"requires_document","objectId":"passport_or_foreign_permanent_resident_id"}]},"connectivity_plan_allowances":{"scene":"connectivity","claims":[{"subjectId":"china_carrier_sim_application","predicate":"requires_action","objectId":"plan_allowance_check"}]},"connectivity_getting_started":{"scene":"connectivity","claims":[{"subjectId":"china_carrier_sim_application","predicate":"requires_document","objectId":"passport_or_foreign_permanent_resident_id"},{"subjectId":"china_carrier_sim_application","predicate":"requires_action","objectId":"plan_allowance_check"}]}}'::jsonb -> p_id
$$;
revoke all on function knowledge_review_private.question_definition(text) from public,anon,authenticated,service_role;

alter table turn_private.grounded_turns drop constraint grounded_turns_intent_check;
alter table turn_private.grounded_turns add constraint grounded_turns_intent_check
 check(intent in ('rail_boarding_documents','payment_card_acceptance','payment_mobile_setup','payment_cash_access','payment_card_and_mobile','payment_card_and_cash','payment_mobile_and_cash','payment_getting_started','connectivity_sim_documents','connectivity_plan_allowances','connectivity_getting_started','clarification','unsupported','technical_failure','blocked'));
